// 将不同入口(IMAP/Webhook/渠道API)的原始消息统一为内部结构
// IMAP 解析结果常见字段: from / to / date / subject / text / html
// Webhook 渠道常见字段: from / sender / subject / body / content / message / channel / receivedAt
const items = $input.all().map(({ json }) => {
  const rawBody = json.body ?? json.text ?? json.content ?? json.message ?? '';
  return {
    json: {
      messageId: json.messageId ?? json.uid ?? json.id ?? String(Date.now()),
      channel: json.channel ?? 'email', // email / telegram / web_form / comment ...
      from: json.from ?? json.sender ?? json.fromEmail ?? json.from_email ?? '',
      to: json.to ?? '',
      subject: json.subject ?? json.title ?? '(无主题)',
      body: String(rawBody).slice(0, 20000),
      receivedAt: json.receivedAt ?? json.date ?? json.received_at ?? new Date().toISOString(),
    },
  };
});
return items;

// 人工审批开关：false = 草稿进入人工待审队列（推荐首月使用）；true = AI 草稿自动发送
// 接入真实系统后，可把 autoSend 改为读取数据库/环境变量（例如 {{AUTO_SEND_SWITCH}}），
// 或按规则自动降级：低置信度、投诉类、含附件/链接请求一律强制人审。
const inputItem = $input.first().json;
const autoSend = false; // TODO: 交付时按客户合同设置；敏感客户默认保持 false
const reviewRequiredByRule =
  (inputItem.category === 'complaint') ||
  (Number(inputItem.confidence ?? 1) < 0.6);
const effectiveAutoSend = autoSend && !reviewRequiredByRule;
return [{
  json: {
    ...inputItem,
    draft: inputItem.data?.draft ?? inputItem.draft ?? '',
    confidence: inputItem.data?.confidence ?? inputItem.confidence ?? 1,
    autoSend: effectiveAutoSend,
  },
}];

// 人工审批分支：给草稿打 pending_review 标记，生成队列 ID，并拼通知文本
const inputItem = $input.first().json;
const queueId = 'q-' + (inputItem.messageId || Date.now());
return [{
  json: {
    ...inputItem,
    queueId: queueId,
    dbStatus: 'pending_review',
    notifyText:
      '[AI邮件助手-待审] ' + (inputItem.subject || '(无主题)') +
      '\n分类: ' + (inputItem.category || 'unknown') +
      '\n拟稿: ' + String(inputItem.draft || '').slice(0, 2000),
  },
}];
